-- Materi BEM-16 (Blok 16 Sistem Endokrin & Metabolisme): 32 bab PDF dalam 7 kelompok.
-- Mengikuti pola impor BRS-13; berkas PDF & gambar halaman sudah ada di storage server.
-- Aman dijalankan pada database kosong (semua INSERT bergantung pada Blok BEM-16 yang ada).

-- Topik lama yang masih terbit (contoh 'Bab 1') disembunyikan, riwayatnya tetap.
UPDATE Topic SET published = false WHERE categoryId = (SELECT id FROM Category WHERE code = 'BEM-16') AND published = true AND id NOT LIKE 'dea-bem16-%';
-- Deskripsi kelas bawaan menyebut kuis per Bab; diganti hanya bila belum diubah admin.
UPDATE Category SET description = 'Blok 16 tahap akademik (preklinik). 32 bab sistem endokrin dan metabolisme dalam 7 bagian, dari struktur dan fisiologi hingga penyakit serta farmakologi endokrin. Bagian 1 (bab 1–5) gratis untuk akun terdaftar.' WHERE code = 'BEM-16' AND description LIKE 'Blok 16 tahap akademik (preklinik). Materi dibagi per Bab%';

